using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;

// Provided infrastructure — do not modify. A string-op counter wired into
// the workload helpers: Concat loops through solution code still count.
public static class StringOps
{
    public static int Allocations { get; private set; }
    public static void Reset() => Allocations = 0;
    public static void Bump() => Allocations++;
}

